class Solution { fun numberWays(hats:List<List<Int>>):Int{val people=hats.size;val mod=1_000_000_007L;val wearers=Array(41){mutableListOf<Int>()};for(person in 0 until people)for(hat in hats[person])wearers[hat].add(person);var dp=LongArray(1 shl people);dp[0]=1;for(hat in 1..40){val next=dp.copyOf();for(mask in dp.indices)if(dp[mask]>0)for(person in wearers[hat])if(mask and (1 shl person)==0){val newMask=mask or (1 shl person);next[newMask]=(next[newMask]+dp[mask])%mod};dp=next};return dp.last().toInt()} }
